// src/App.js
import React, { useState, useEffect } from 'react';
import GlobalStyle from './styles/GlobalStyle';
import styled from 'styled-components';

import Header from './components/Header';
import Equipment from './components/Equipment';
import EquipmentSearch from './components/EquipmentSearch';
import SelectedSidebar from './components/SelectedSidebar';
import TrainingTips from './components/TrainingTips';
import { trainingTipsData } from './data/trainingTipsData'; // Import the data correctly

const MainContainer = styled.div`
  display: flex;
  justify-content: space-between;
  margin: 20px auto;
  max-width: 1200px;
`;

const ContentArea = styled.div`
  flex: 2;
  padding-right: 20px;
`;

const SidebarArea = styled.div`
  flex: 1;
  padding-left: 20px;
`;

function App() {
  const [equipmentData, setEquipmentData] = useState([]); // Full equipment data
  const [filteredEquipment, setFilteredEquipment] = useState([]); // Data after filtering
  const [selectedEquipment, setSelectedEquipment] = useState([]);

  // Fetch equipment data from Flask or use mock data
  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch('http://localhost:5000/api/competitivecyclist');
        const data = await response.json();
        setEquipmentData(data); // Set the full data
        setFilteredEquipment(data); // Initialize with all data
      } catch (error) {
        console.error('Error fetching data:', error);
      }
    };
    fetchData();
  }, []);

  // Handle search input to filter the equipment list
  const handleSearch = (searchTerm) => {
    if (searchTerm === '') {
      setFilteredEquipment(equipmentData); // Reset to full data when search is cleared
    } else {
      const filtered = equipmentData.filter((item) =>
        item.Name.toLowerCase().includes(searchTerm.toLowerCase())
      );
      setFilteredEquipment(filtered);
    }
  };

  // Handle equipment selection and toggle it in the selected list
  const handleSelect = (item) => {
    const itemWithPrice = { ...item, price: item.price || '$100' }; // Example pricing
    setSelectedEquipment((prev) =>
      prev.find((i) => i.id === itemWithPrice.id)
        ? prev.filter((i) => i.id !== itemWithPrice.id) // Remove if already selected
        : [...prev, itemWithPrice] // Add if not selected
    );
  };

  const handleRemoveItem = (id) => {
    setSelectedEquipment(selectedEquipment.filter((item) => item.id !== id));
  };

  return (
    <>
      <GlobalStyle />
      <Header />

      <MainContainer>
        <ContentArea>
          <EquipmentSearch onSearch={handleSearch} />
          <Equipment equipment={filteredEquipment} handleSelect={handleSelect} />
          <TrainingTips tips={trainingTipsData} />
        </ContentArea>

        <SidebarArea>
          <SelectedSidebar selectedItems={selectedEquipment} removeItem={handleRemoveItem} />
        </SidebarArea>
      </MainContainer>
    </>
  );
}

export default App;
